#!/bin/bash
set -euo pipefail
APP_DIR="/opt/handheld-hub"
echo '==> deploy blogger en-only + release_date order'
echo '' | base64 -d > "\/lib/blogger.php"
echo '' | base64 -d > "\/admin/blogger.php"
php -l "\/lib/blogger.php" >/dev/null
php -l "\/admin/blogger.php" >/dev/null
grep -q 'hh_blogger_sort_handheld_ids_for_publish' "\/lib/blogger.php" && echo 'lib ok'
grep -q '发布时间从旧到新' "\/admin/blogger.php" && echo 'admin ok'
echo '==> done'